def phase_started_at(self, state):
    """当前阶段的开始时间（用事务的 updated_at 近似）。

    `updated_at` 是 **UTC**（控制器用 `time.gmtime()` 写出，带 `Z` 后缀），
    所以必须用 `calendar.timegm()` 解析。

    这里曾经写的是 `time.mktime(parsed) - time.timezone`：`mktime` 按
    **本地时间**解释，减去 `timezone`（标准时差）只在"当前偏移 == 标准
    偏移"时才碰巧正确。在实行夏令时的时区（Europe/Berlin、America/New_York）
    夏季会固定偏差 1 小时，方向是**把起始时间算早** → `elapsed` 偏大 1h →
    健康窗口提前耗尽 → 健康的候选被回滚（叠加 EXIT_RETRY 还会请求重启）。
    工业网关现场改时区很常见，不能靠"板端是 UTC"兜住。
    """
    if not state.has_tx or not state.updated_at:
        return self.rec.clock()
    try:
        parsed = time.strptime(state.updated_at, "%Y-%m-%dT%H:%M:%SZ")
    except (ValueError, TypeError):
        return self.rec.clock()
    return calendar.timegm(parsed)

