    info.rssiHistory = {-55};
    EXPECT_EQ(info.rssiLevel(), "good");

    info.rssiHistory = {-65};
    EXPECT_EQ(info.rssiLevel(), "fair");

    info.rssiHistory = {-75};
    EXPECT_EQ(info.rssiLevel(), "poor");

    info.rssiHistory = {-85};
    EXPECT_EQ(info.rssiLevel(), "very_poor");
}
